from typing import List

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        prefix = [0]
        for num in nums:
            prefix.append(prefix[-1] + num)
        best = -float("inf")
        for right in range(k, len(nums) + 1):
            best = max(best, prefix[right] - prefix[right - k])
        return best / k

